const SERVICE_NAME = "kitesurf-local";
const ZERO_SPAN_ID = "0000000000000000";
const TRACE_ID_RE = new RegExp(
  `^([0-9a-f]{${SHORT_TRACE_ID_HEX_CHARS}}|[0-9a-f]{${TRACE_ID_HEX_CHARS}})$`,
